<script lang="ts">
 import { enhance } from '$app/forms';
 import { formatCurrency } from '$lib/utils/format';
 import type { PageProps } from './$types';
 let { data, form }: PageProps = $props();
 let busy = $state(false);
 const signature = $derived(form?.approvalSignature ?? data.draft.approvalSignature);
 const signedTime = (value: string) => new Date(value).toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'long', timeStyle: 'short' });
 const canSign = $derived(Boolean(data.draft.documentHash && data.draft.approvalConsentText && data.draft.approvalConsentVersion));
 const pricing = $derived(data.draft.locksmithPricing);
 const decision = $derived(form?.approved ? 'approved' : form?.changesRequested ? 'changes-requested' : data.draft.delivery?.status);
 const date = (value: string) => new Date(value).toLocaleDateString('en-US', { timeZone: 'America/New_York', month: 'long', day: 'numeric', year: 'numeric' });
 const submit = () => { busy = true; return async ({ update }: { update: () => Promise<void> }) => { try { await update(); } finally { busy = false; } }; };
</script>
<svelte:head><title>Quote review · Carl Zipf Lock Shop</title><meta name="robots" content="noindex,nofollow" /><meta name="referrer" content="no-referrer" /></svelte:head>
<div class="review-background"><main class="review">
 <header><a href="/carlzipf/public"><img src="/carlzipf/logo.jpg" alt="Carl Zipf Lock Shop" width="220" height="74" /></a><a href="tel:+16142997303">Questions? 614-299-7303</a></header>
 <section class="summary"><div><p class="eyebrow">Your quote · Revision {data.draft.revisionNumber}</p><h1>{data.draft.customerName}</h1><p>{data.draft.siteName}</p><p>{data.draft.serviceSummary}</p></div><div class="total"><span>Quote total</span><strong>{formatCurrency(data.draft.totals.estimatedTotal)}</strong>{#if data.draft.expiresAtUtc}<small>Review by {date(data.draft.expiresAtUtc)}</small>{/if}</div></section>
 {#if decision === 'approved'}<section class="notice" role="status"><h2>Quote approved</h2><p>Your approval has been recorded for revision {data.draft.revisionNumber}. We’ll contact you about next steps. An installation appointment has not been booked through this approval.</p>{#if signature}<p><strong>Electronically signed by {signature.signerPrintedName}</strong><br />{signedTime(signature.signedAtUtc)} (Eastern time) · Revision {signature.revisionNumber}</p><p>{signature.consentText}</p>{:else if data.draft.delivery?.approvedAtUtc}<small>Approval recorded {date(data.draft.delivery.approvedAtUtc)}. A typed signature was not recorded for this earlier approval.</small>{/if}</section>
 {:else if decision === 'changes-requested'}<section class="notice" role="status"><h2>Changes requested</h2><p>Your note has been saved. Our team will review it and send an updated quote when ready.</p>{#if data.draft.delivery?.responseNote}<blockquote>{data.draft.delivery.responseNote}</blockquote>{/if}</section>{/if}
 {#if form?.decisionError}<p class="error" role="alert">{form.decisionError}</p>{/if}
 <section><h2>Included work</h2><ul>{#each data.draft.scopeLineItems as item}<li>{item}</li>{/each}</ul>{#if !data.draft.scopeLineItems.length}<p>{data.draft.serviceSummary}</p>{/if}</section>
 {#if pricing}
 <section><h2>Doors & hardware</h2><div class="line-items">{#each pricing.lines as line}<article><div><h3>{line.name}</h3><p>{line.openingName} · {line.quantity} × {formatCurrency(line.unitPrice)}</p></div><strong>{formatCurrency(line.total)}</strong></article>{/each}</div>
 <dl class="totals"><div><dt>Products & hardware</dt><dd>{formatCurrency(data.draft.totals.materialCost)}</dd></div><div><dt>Labor ({pricing.laborHours} hours)</dt><dd>{formatCurrency(data.draft.totals.laborCost)}</dd></div><div><dt>Subtotal</dt><dd>{formatCurrency(pricing.subtotal)}</dd></div>{#if pricing.discountAmount}<div><dt>Discount ({pricing.discountPercent}%)</dt><dd>−{formatCurrency(pricing.discountAmount)}</dd></div>{/if}<div><dt>Tax ({pricing.taxPercent}%)</dt><dd>{formatCurrency(pricing.taxAmount)}</dd></div><div class="grand-total"><dt>Quote total</dt><dd>{formatCurrency(data.draft.totals.estimatedTotal)}</dd></div></dl></section>
 {#if pricing.openings.length}<section><h2>Openings</h2><div class="openings">{#each pricing.openings as opening}<article><h3>{opening.name}</h3><p>{opening.service}</p>{#if opening.handing}<p>Handing / swing: {opening.handing}</p>{/if}{#if opening.notes}<p class="preserve">{opening.notes}</p>{/if}{#if opening.commercialNotes}<p class="preserve">{opening.commercialNotes}</p>{/if}</article>{/each}</div></section>{/if}
 {/if}
 {#if data.draft.notes || data.draft.assumptions.length}<section><h2>Notes & assumptions</h2>{#if data.draft.notes}<p class="preserve">{data.draft.notes}</p>{/if}<ul>{#each data.draft.assumptions as item}<li>{item}</li>{/each}</ul></section>{/if}
 {#if decision === 'sent'}<section><h2>Ready to move forward?</h2><p>Review the scope and total above. Approval lets our team arrange next steps. Scheduling, payment, and acceptance of completed work are handled separately.</p><form method="POST" action={`?/approve&token=${encodeURIComponent(data.accessToken)}`} use:enhance={submit}><input type="hidden" name="accessToken" value={data.accessToken} /><input type="hidden" name="revisionNumber" value={data.draft.revisionNumber} /><input type="hidden" name="documentHash" value={data.draft.documentHash ?? ''} /><input type="hidden" name="consentVersion" value={data.draft.approvalConsentVersion ?? ''} /><label class="signer">Your printed name<input name="signerPrintedName" autocomplete="name" maxlength="200" required value={form?.signerPrintedName ?? ''} /></label><label class="consent"><input type="checkbox" name="intentToSign" value="yes" required /><span>{data.draft.approvalConsentText || 'Signing details are unavailable. Please reload this quote.'}</span></label><button disabled={busy || !canSign}>{busy ? 'Saving…' : 'Sign & approve quote'}</button></form><details><summary>Something needs to change?</summary><form method="POST" action={`?/requestChanges&token=${encodeURIComponent(data.accessToken)}`} use:enhance={submit}><input type="hidden" name="accessToken" value={data.accessToken} /><label for="changes">Tell us what to adjust</label><textarea id="changes" name="responseNote" rows="4" maxlength="2000" required value={form?.responseNote ?? ''}></textarea><button class="secondary" disabled={busy}>Request changes</button></form></details></section>{/if}
 <footer>Carl Zipf Lock Shop · 161 East Fifth Avenue, Columbus, Ohio 43201<br /><a href="tel:+16142997303">614-299-7303</a></footer>
</main></div>
<style>
 .review-background{background:#faf9f5;min-height:100vh}.review{max-width:900px;margin:auto;padding:24px;color:#213a32;line-height:1.6}.review header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:30px}.review header a{font-size:13px;color:inherit}.review header img{width:200px;height:auto}.review section{padding:28px;background:white;border:1px solid #dce2d9;border-radius:6px;margin:20px 0}.summary{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.1em}h1,p{overflow-wrap:anywhere}h1{font-size:30px;margin:8px 0;line-height:1.2}h2{font-size:21px;margin:0 0 12px}h3{font-size:15px;margin:0}p{font-size:14px;color:#56655e;margin:10px 0}.total{display:flex;flex-direction:column;justify-content:center;gap:8px;text-align:right}.total span,small{font-size:12px}.total strong{font-size:32px}.notice{background:#eef4e9!important}.error{background:#fff1ed;border:1px solid #e6b9a8;padding:18px;color:#852d21}.review ul{padding-left:20px;font-size:14px}.line-items article{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid #e3e7df}.line-items article>strong{white-space:nowrap;font-size:14px}.line-items p{margin:5px 0}.totals{margin:24px 0 0 auto;max-width:400px;font-size:14px}.totals>div{display:flex;justify-content:space-between;gap:20px;margin:9px 0}.totals dd{margin:0}.grand-total{font-weight:700;border-top:1px solid #dce2d9;padding-top:12px;font-size:18px}.openings{display:grid;grid-template-columns:1fr 1fr;gap:15px}.openings article{background:#f7f8f4;padding:15px;border-radius:4px}.preserve,blockquote{white-space:pre-wrap;overflow-wrap:anywhere}.signer{display:block;font-size:14px;margin-top:20px}.signer input{display:block;width:100%;box-sizing:border-box;border:1px solid #b9c5b7;border-radius:4px;padding:12px;margin-top:8px;font:inherit}.consent{display:flex;gap:12px;align-items:flex-start;font-size:14px;margin:22px 0}.consent input{margin-top:5px;accent-color:#213a32}button{background:#213a32;color:white;border:0;border-radius:4px;padding:13px 22px;font-size:14px;font-weight:600;min-height:46px;cursor:pointer}button:disabled{opacity:.5;cursor:wait}details{margin-top:28px;border-top:1px solid #dce2d9;padding-top:18px}summary{cursor:pointer;font-weight:600;font-size:14px}details label{display:block;margin:18px 0 8px;font-size:14px}textarea{width:100%;box-sizing:border-box;border:1px solid #b9c5b7;border-radius:4px;padding:12px;font:inherit;margin-bottom:12px}.secondary{background:white;color:#213a32;border:1px solid #213a32}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible,textarea:focus-visible{outline:3px solid #78916d;outline-offset:3px}footer{text-align:center;font-size:12px;color:#68756d;margin:30px 0}footer a{color:inherit}@media(max-width:600px){.review{padding:16px}.review header{align-items:start}.review header img{width:145px}.review header a:last-child{max-width:120px;text-align:right}.review section{padding:20px}.summary{grid-template-columns:1fr}.total{text-align:left}.openings{grid-template-columns:1fr}button{width:100%}h1{font-size:25px}}
</style>
